package com.example.erp.repository;
import com.example.erp.entity.*;
import java.util.*;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
public interface InvoiceRepository extends JpaRepository<Invoice,UUID> { Optional<Invoice> findByIdAndOrganizationId(UUID id,UUID organizationId); @Query("select i from Invoice i join Customer c on c.id=i.customerId where i.organizationId=:org and (:keyword='' or lower(coalesce(i.invoiceNumber,'')) like lower(concat('%',:keyword,'%')) or lower(c.name) like lower(concat('%',:keyword,'%'))) and (:status is null or i.status=:status) and (:fromDate is null or i.invoiceDate>=:fromDate) and (:toDate is null or i.invoiceDate<=:toDate)") Page<Invoice> search(@Param("org") UUID org,@Param("keyword") String keyword,@Param("status") InvoiceStatus status,@Param("fromDate") java.time.LocalDate fromDate,@Param("toDate") java.time.LocalDate toDate,Pageable pageable); @Query("select i from Invoice i join Customer c on c.id=i.customerId where i.organizationId=:org and i.status=com.example.erp.entity.InvoiceStatus.ISSUED and i.balanceDue>0 and i.dueDate< CURRENT_DATE and (:keyword='' or lower(coalesce(i.invoiceNumber,'')) like lower(concat('%',:keyword,'%')) or lower(c.name) like lower(concat('%',:keyword,'%'))) and (:fromDate is null or i.invoiceDate>=:fromDate) and (:toDate is null or i.invoiceDate<=:toDate)") Page<Invoice> searchOverdue(@Param("org") UUID org,@Param("keyword") String keyword,@Param("fromDate") java.time.LocalDate fromDate,@Param("toDate") java.time.LocalDate toDate,Pageable pageable); }
